{
  "id": "animation-anchors",
  "title": "Track contacts and review loop closure",
  "applies_to": [
    "walk cycles",
    "idle loops",
    "weapon actions"
  ],
  "requires": [
    "Named anchors, ground line and expected contact intervals"
  ],
  "procedure": [
    "Track contact-point coordinates independently from each frame's crop rectangle.",
    "Use onion-skin or difference views to compare adjacent poses and last-to-first transition.",
    "Permit displacement where the action demands it; lock only specified contacts."
  ],
  "checks": [
    "Required planted contacts remain fixed through their contact interval.",
    "The loop boundary obeys the same motion policy as internal transitions."
  ],
  "pitfalls": [
    "A moving root can coexist with a visually planted foot only after world-space compensation.",
    "A low pixel-difference score does not prove a convincing animation."
  ],
  "sources": [
    {
      "path": "training/original-docs/PIXEL-ART-DEEP-RESEARCH.md",
      "start": 476,
      "end": 500
    },
    {
      "path": "training/original-docs/PIXEL-ART-DEEP-RESEARCH.md",
      "start": 1552,
      "end": 1573
    }
  ],
  "poc": {
    "kind": "timeline-fixture",
    "procedure": [
      "Create three 16x16 frames with a foot anchor at (8,14), varying only a body highlight.",
      "Mutate the final frame's anchor to (9,14) and inspect last-to-first displacement."
    ],
    "acceptance": [
      "Original has zero foot displacement on every transition.",
      "Mutant reports a one-pixel contact jump."
    ]
  }
}

{
  "id": "frame-timing",
  "title": "Author duration and event semantics per frame",
  "applies_to": [
    "sprite animation",
    "attacks",
    "idle loops",
    "UI feedback"
  ],
  "requires": [
    "Ordered frame IDs, positive durations and loop or one-shot policy"
  ],
  "procedure": [
    "Store durations explicitly rather than assuming uniform FPS.",
    "Name anticipation, action, impact and settle events where relevant.",
    "Define half-open time intervals so event and frame boundaries have no ambiguity."
  ],
  "checks": [
    "Every duration is positive and playback reaches the expected frame at boundary times.",
    "One-shot terminal states and looping wrap behavior are explicit."
  ],
  "pitfalls": [
    "More frames do not automatically improve weight or readability.",
    "Unspecified preview FPS must not overwrite authored durations."
  ],
  "sources": [
    {
      "path": "training/original-docs/PIXEL-ART-DEEP-RESEARCH.md",
      "start": 869,
      "end": 905
    },
    {
      "path": "training/original-docs/PIXEL-ART-ASSETS.md",
      "start": 948,
      "end": 960
    }
  ],
  "poc": {
    "kind": "timeline-fixture",
    "procedure": [
      "Use frames A,B,C with durations 80,40,120 milliseconds and a looping total of 240.",
      "Sample t=0,79,80,119,120,239,240 using half-open intervals."
    ],
    "acceptance": [
      "Frame IDs are A,A,B,B,C,C,A.",
      "An impact event at 120 fires once per loop crossing."
    ]
  }
}

{
  "id": "silhouette-readability",
  "title": "Evaluate identity using silhouette and target backgrounds",
  "applies_to": [
    "characters",
    "inventory icons",
    "interactive props"
  ],
  "requires": [
    "Intended viewing scale, representative backgrounds and identity landmarks",
    "Applicability judgment: the cited cluster constraints, temporal-change discussion and UI brief support feature preservation and contextual clarity; they do not prescribe the flat-mask or multi-background procedure below."
  ],
  "procedure": [
    "Treat this inspection sequence as a curated expert diagnostic proposal. Select the views that answer the current asset question; do not attribute the sequence itself to the cited passages or make it an owner requirement.",
    "Render a flat opaque mask before detailing.",
    "Inspect major proportions, negative spaces and landmark separation at native logical scale.",
    "Compare the colored asset on representative light, dark and busy backgrounds."
  ],
  "checks": [
    "Named identity landmarks remain visible at the target size.",
    "Required gaps stay open and interactive forms separate from their surroundings."
  ],
  "pitfalls": [
    "Silhouette alone cannot validate faces, materials or fine symbols.",
    "No contrast ratio or component count proves aesthetic quality.",
    "The cited temporal silhouette-change condition is animation-specific; it does not impose a static-icon construction rule. The key fixture proves its landmark checks only, not universal aesthetic validity."
  ],
  "sources": [
    {
      "path": "training/original-docs/PIXEL-ART-DEEP-RESEARCH.md",
      "start": 857,
      "end": 867
    },
    {
      "path": "training/original-docs/PIXEL-ART-DEEP-RESEARCH.md",
      "start": 1563,
      "end": 1573
    },
    {
      "path": "training/original-docs/PIXEL-ART-ASSETS.md",
      "start": 11,
      "end": 15
    }
  ],
  "poc": {
    "kind": "visual-review-fixture",
    "procedure": [
      "Draw a 16x16 key with a ring hole, shaft and two teeth; render mask and colored views on three backgrounds.",
      "Create a negative example by filling the hole and merging the teeth."
    ],
    "acceptance": [
      "Record native-scale contact sheets and explicit pass/fail for hole, shaft and both teeth.",
      "Negative example fails the landmark checklist; aesthetic review remains separate."
    ]
  }
}

